let toastTimer;
// An optional action (such as Undo) makes the toast clickable and keeps it up a little longer.
function toast(t,action){const el=$('#toast');clearTimeout(toastTimer);el.innerHTML=esc(t)+(action?`<button type="button" class="toast-action">${esc(action.label)}</button>`:'');el.classList.toggle('has-action',!!action);if(action)el.querySelector('.toast-action').onclick=()=>{clearTimeout(toastTimer);el.classList.remove('visible');action.run()};el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),action?7000:3000)}
function err(e){toast(e.message||'Something went wrong. Please try again.')}
function reading(k){return readings.find(r=>r.kind===k)}
// A wearable reading older than a few days is shown as "last recorded", never as today's value.
const isStale=m=>m.group!=='body'&&!!staleDays(reading(m.kind));
const freshFirst=list=>[...list].sort((a,b)=>Number(isStale(a))-Number(isStale(b)));
// The latest reading against the person's other recent days (compareLatest): the one baseline every surface uses.
// A neutral badge for an ordinary change; the orange badge only when the reading is unusual for them.
function latestChange(own,r){const compare=r&&!staleDays(r)?compareLatest(own,r):null,delta=compare?metricDelta(r.value,compare.mean):null,unusual=!!(delta&&compare.unusual);return {delta,unusual,badge:delta?`<span class="badge ${unusual?'':'quiet'}" title="${unusual?'Unusual for you: outside your usual 30-day range. ':''}${esc(delta.title)}">${unusual?'Unusual · ':''}${esc(delta.label)}</span>`:''}}
// Signals with no reading in the last 30 days get one compact line at the end of the page, not a card.
const dormant=m=>staleDays(reading(m.kind))>30;
function dormantRow(list){const old=list.filter(m=>reading(m.kind)&&dormant(m));return old.length?`<p class="dormant-row"><span>Not recorded recently:</span>${old.map(m=>`<button class="text-button" data-metric="${m.kind}">${esc(m.name)} · last ${new Date(reading(m.kind).observed_at).toLocaleDateString(dateLocale,{month:'short',day:'numeric'})}</button>`).join('')}</p>`:''}
// The source most of the page's signals come from; the page lead names it, so cards only name a different one.
function pageSource(list){const n=new Map();for(const m of list){const s=reading(m.kind)?.source;if(s)n.set(s,(n.get(s)||0)+1)}return [...n].sort((a,b)=>b[1]-a[1])[0]?.[0]||''}
// Metric cards for Vitals and Sleep: value and unit, the change badge (or "Last <date>" when the reading is old),
// the same in words, the last 14 days, then the 30-day average.
function cards(list=metrics,heroKind=null,source=''){return list.map(m=>{const r=reading(m.kind),own=readings.filter(x=>x.kind===m.kind&&x.source===r?.source&&x.unit===r?.unit),average=metricSummary(metricSeries(own,m.kind,30)),date=r?new Date(r.observed_at).toLocaleDateString(dateLocale,{month:'short',day:'numeric'}):'',stale=m.group!=='body'?staleDays(r):0,{delta,unusual,badge:change}=latestChange(own,r);
 const day=r?(localDay(new Date(r.observed_at))===localDay()?(m.group==='sleep'?'Last night':'Today'):localDay(new Date(r.observed_at))===localDay(new Date(Date.now()-86400000))?'Yesterday':date):'';
 const badge=stale?`<span class="badge quiet" title="Last reading ${stale} days ago">Last ${date}</span>`:change;
 const status=!r?'':stale?`Last recorded ${date}, no reading in ${stale} days`:unusual?'Outside your usual 30-day range':delta?delta.title:'';
 const caption=!r?'':stale?`No reading in the last ${stale} days`:`${day}${status?' · '+esc(status):''}`;
 const foot=r?[r.source!==source?esc(r.source):'',average.mean!==null?`30-day avg <b>${formatValue(average.mean,m.kind)}</b>${m.unit?' '+esc(m.unit):''}`:`Last recorded ${date}`]:[m.group==='body'?'Add your measurement':'Connect a source'];
 const hero=m.kind===heroKind,recent=hero?metricSummary(metricSeries(own,m.kind,30),{days:14}):null,unit=m.unit?' <small>'+esc(m.unit)+'</small>':'',cells=recent?.days?[['14-day low',formatValue(recent.min,m.kind)+unit],['14-day high',formatValue(recent.max,m.kind)+unit],['Days recorded',`${recent.days} <small>of 14</small>`]]:[];
 return vcard({m,r,rows:own,badge,caption,status,foot,cells,hero,stale:!!stale,readings,empty:m.group==='body'?'Add a measurement to get started':'No reading yet'})}).join('')}

// Vitals: one focal dark card (recovery when it is current, otherwise the freshest signal), then white cards.
function vitalsPage(){const available=freshFirst(metrics.filter(m=>m.group!=='sleep'&&m.group!=='body'&&reading(m.kind))),shown=available.filter(m=>!dormant(m)),list=available.length?shown:metrics.slice(0,6).filter(m=>m.kind!=='sleep'),hero=shown.find(m=>m.kind==='recovery'&&!isStale(m))||shown.find(m=>!isStale(m)),ordered=hero?[hero,...list.filter(m=>m!==hero)]:list;return `${available.length?'':dataCallout()}<div class="metric-grid vitals-grid">${cards(ordered,hero?.kind,pageSource(available))}</div>${dormantRow(available)}`}
// Sleep: last night as the focal dark card, goals on the forest card, then one white card per sleep signal.
function sleepPage(){const latest=reading('sleep'),stale=latest?staleDays(latest):0,lastNight=latest&&!stale?latest:null,stages=lastNight?[['sleep_deep','Deep','accent'],['sleep_rem','REM','violet'],['sleep_light','Light','green']].map(([kind,name,tone])=>({kind,name,tone,row:readings.find(r=>r.kind===kind&&r.source===latest?.source&&r.observed_at.slice(0,10)===latest?.observed_at.slice(0,10))})).filter(s=>s.row):[];
 // Stage figures are rounded so they add up to the hours shown, instead of 8.4 h of stages in an 8.3 h night.
 const shown=apportion(stages.map(s=>Number(s.row.value)),Number(latest?.value||0));stages.forEach((s,i)=>s.shown=shown[i]);const all=freshFirst(metrics.filter(m=>m.group==='sleep'&&reading(m.kind))),list=all.filter(m=>m.kind!=='sleep'&&!dormant(m)),source=pageSource(all);return `${latest?'':dataCallout()}<div class="metric-grid sleep-grid">${latest?sleepHero(latest,stale,stages,source)+goalsPanel():''}${cards(latest?list:metrics.filter(m=>['sleep','sleep_performance','sleep_efficiency'].includes(m.kind)),null,source)}</div>${dormantRow(all.filter(m=>m.kind!=='sleep'))}`}
// The latest night: hours, the change against the 30-day average, the stage split and the last 14 nights.
function sleepHero(latest,stale,stages,source){
 const m=metrics.find(x=>x.kind==='sleep'),own=readings.filter(x=>x.kind==='sleep'&&x.source===latest.source&&x.unit===latest.unit),average=metricSummary(metricSeries(own,'sleep',30)),{delta,unusual,badge:change}=latestChange(own,latest),at=new Date(latest.observed_at),short=at.toLocaleDateString(dateLocale,{month:'short',day:'numeric'}),hours=v=>v.toLocaleString(dateLocale,{maximumFractionDigits:1});
 const badge=stale?`<span class="badge quiet" title="Last reading ${stale} days ago">Last ${short}</span>`:change;
 const chart=metricVisual(m,own,{readings});
 return `<section class="card dark sleep-hero ${stale?'is-stale':''}" aria-labelledby="sleep-hero-title"><div class="card-head"><span class="marker" aria-hidden="true"></span><h2 id="sleep-hero-title">${stale?'Last recorded night':'Last night'} <span class="muted">· ${at.toLocaleDateString(dateLocale,{weekday:'long',month:'long',day:'numeric'})}</span></h2><span class="spacer"></span>${badge}<button class="icon-btn small" data-metric="sleep" aria-label="Open sleep details">${icon('arrow')}</button></div><div class="sleep-hero-body"><div class="sleep-hero-main"><div class="stat"><b>${formatValue(latest.value,'sleep')}</b><small>hours asleep</small></div><span class="stat-caption">${stale?`${esc(latest.source)} has not recorded a night in the last ${stale} days. Older readings are shown below with their date.`:unusual?'Outside your usual 30-day range · '+esc(delta.title):delta?esc(delta.title):'The comparison with your other nights appears after three recorded nights.'}</span>${stages.length?`<div class="stage-bar" role="img" aria-label="${stages.map(s=>`${s.name} ${hours(s.shown)} hours`).join(', ')}">${stages.map(s=>`<i class="t-${s.tone}" style="flex:${Number(s.row.value)}"></i>`).join('')}</div><ul class="stage-list">${stages.map(s=>`<li><i class="t-${s.tone}" aria-hidden="true"></i><span>${s.name}</span><b>${hours(s.shown)}<small> h</small></b></li>`).join('')}</ul>`:''}</div>${chart?`<div class="sleep-hero-chart">${chart}</div>`:''}</div><div class="sleep-hero-foot">${latest.source!==source?`<span>${esc(latest.source)}</span>`:''}<span>${average.mean!==null?`30-day avg <b>${formatValue(average.mean,'sleep')}</b> hours`:`Last recorded ${short}`}</span></div></section>`;
}
// Goals are the person's own; debt adds up shortfalls only, so a long night does not cancel a short one.
const preferences=()=>({sleep_goal:8,recovery_goal:66,...(data.user?.user_metadata?.preferences||{})});
function goalsPanel(){const {sleep_goal:goal,recovery_goal:rgoal}=preferences(),night=reading('sleep'),own=readings.filter(r=>r.kind==='sleep'&&r.source===night?.source),now=Date.now(),sum=sleepGoalSummary(own,goal,{now}),before=sleepGoalSummary(own,goal,{now:now-7*86400000}),rec=reading('recovery'),recDays=dailyMeans(readings.filter(r=>r.kind==='recovery'&&r.source===rec?.source),{days:14}),hours=v=>v.toLocaleString(dateLocale,{maximumFractionDigits:1}),change=sum.debt-before.debt,scale=goal*1.4;
 const nights=sum.days,dayLabel=d=>new Date(d.day+'T12:00:00Z').toLocaleDateString(dateLocale,{timeZone:'UTC',month:'short',day:'numeric'});
 const row=(name,note,value,unit)=>`<li class="goal-row"><span class="goal-name"><b>${name}</b><small>${note}</small></span><span class="goal-value"><b>${value}</b><small>${unit}</small></span></li>`;
 return `<section class="card forest goals-card" aria-labelledby="goals-title"><div class="card-head"><span class="marker" aria-hidden="true"></span><h2 id="goals-title">Your goals</h2><span class="spacer"></span><button class="btn light small" data-action="edit-goals">Change goals</button></div><ul class="goal-list">${row('Sleep goal',nights.length?`Met on ${sum.met} of ${nights.length} recorded nights in the last 14 days`:'No recorded nights in the last 14 days',hours(goal),'h')}${row('Sleep debt · last 7 nights',before.days.length?`${Math.abs(change)<.05?'Same as':`${hours(Math.abs(change))} h ${change>0?'more than':'less than'}`} the 7 nights before`:'Hours below your goal, added up',hours(sum.debt),'h')}${row('Recovery goal',recDays.length?`Reached on ${recDays.filter(d=>d.value>=rgoal).length} of ${recDays.length} days in the last 14`:'No recovery readings in the last 14 days',rgoal,'%')}</ul>${nights.length?`<div class="goal-chart"><span class="goal-chart-title">Last ${nights.length} recorded nights</span><div class="goal-bars" role="img" aria-label="Sleep on the last ${nights.length} recorded nights against your ${hours(goal)} hour goal">${nights.map(d=>`<i class="${d.value>=goal?'met':''}" style="--h:${Math.min(100,d.value/scale*100).toFixed(1)}%" title="${dayLabel(d)}: ${hours(d.value)} h"></i>`).join('')}<span class="goal-line" style="--g:${(goal/scale*100).toFixed(1)}%"><b>${hours(goal)} h goal</b></span></div><div class="goal-scale"><span>${dayLabel(nights[0])}</span><span>${dayLabel(nights.at(-1))}</span></div><div class="legend"><span><i class="t-accent"></i>Goal met</span><span><i class="goal-key"></i>Below goal</span></div></div>`:''}</section>`}
function editGoals(){const {sleep_goal,recovery_goal}=preferences();showModal(`${heading('Your goals','Sleep')}<p>Set targets that suit you. Xeyo compares your recorded nights and recovery with them.</p><form id="goals-form"><div class="form-grid"><label class="field">Sleep goal (hours)<input name="sleep_goal" type="number" min="4" max="12" step="0.25" required value="${sleep_goal}"></label><label class="field">Recovery goal (%)<input name="recovery_goal" type="number" min="1" max="100" step="1" required value="${recovery_goal}"></label></div><div id="form-error"></div><div class="dialog-footer"><span>Saved to your account.</span><button class="btn" type="submit">Save goals</button></div></form>`);$('#goals-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{const v=new FormData(e.target);await data.savePreferences({sleep_goal:Number(v.get('sleep_goal')),recovery_goal:Number(v.get('recovery_goal'))});closeModal();await render();toast('Goals saved')})}}
function currentBoard(){return boardDraft||normalizeLayout(data.user?.user_metadata?.dashboard_layout)}
async function editDashboard(){if(boardDraft)return;boardDraft=structuredClone(currentBoard());page='Home';await render();document.querySelector('#board-add')?.focus();}
async function redrawBoard(focus){await render();if(focus)document.querySelector(focus)?.focus();}
function bindBoard(){if(!boardDraft)return;bindWidgetEditing($('#page'),{remove:id=>{boardDraft.widgets=boardDraft.widgets.filter(w=>w.id!==id);redrawBoard('#board-add')},move:(id,delta)=>{boardDraft.widgets=moveWidget(boardDraft.widgets,id,boardDraft.widgets.findIndex(w=>w.id===id)+delta);redrawBoard(`[data-step-widget="${id}"][data-step="${delta}"]:not(:disabled)`)}});}
function widgetGallery(){let group='all',search='';showModal(`${heading('Your signals','Home')}<p>Choose up to ${BOARD_LIMIT} signals to follow on Home. Each one uses your own recorded data.</p><label class="field widget-search"><input id="widget-search" type="search" placeholder="Search signals" aria-label="Search signals"></label><div class="widget-categories">${[['all','All'],['vitals','Vitals'],['sleep','Sleep'],['body','Body'],['activity','Activity']].map(([id,n])=>`<button data-widget-group="${id}" aria-pressed="${id===group}">${n}</button>`).join('')}</div><div id="widget-gallery" class="widget-gallery"></div><p id="widget-count" class="mini-note" role="status"></p>`,true);
 // Widgets with data come first; ones nothing has recorded yet are flagged rather than looking ready.
 const hasData=m=>!!reading(m.kind);
 const draw=()=>{const list=widgetCatalog.filter(m=>(group==='all'||m.group===group)&&m.name.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>Number(hasData(b))-Number(hasData(a)));$('#widget-gallery').innerHTML=list.map(m=>{const added=boardDraft.widgets.some(w=>w.id===m.kind),r=reading(m.kind);return `<button class="widget-choice ${m.color} ${m.stroke?'has-accent':''} ${hasData(m)?'':'no-data'}" ${m.stroke?`style="--accent:${m.stroke}"`:''} data-add-widget="${m.kind}" ${added?'disabled':''}><div class="widget-choice-head">${m.stroke?metricIcon(m.kind):''}<span>${m.name}</span><b>${added?'✓':'+'}</b></div><div class="widget-preview-number">${r?formatValue(r.value,m.kind):'—'}<small>${esc(m.unit)}</small></div><small>${added?'On Home':r?esc(r.source):'<b class="no-data-flag">No data yet</b> Shows once a source records it'}</small></button>`}).join('')||'<p>No matching widgets.</p>';$('#widget-count').textContent=`${boardDraft.widgets.length} of ${BOARD_LIMIT} chosen · ${widgetCatalog.filter(hasData).length} of ${widgetCatalog.length} signals have data`;document.querySelectorAll('[data-add-widget]').forEach(b=>b.onclick=async()=>{if(boardDraft.widgets.length>=BOARD_LIMIT){toast(`Home follows up to ${BOARD_LIMIT} signals. Remove one to add another.`);return}boardDraft.widgets.push({id:b.dataset.addWidget,size:'small'});await render();draw();});};
 $('#widget-search').oninput=e=>{search=e.target.value;draw()};document.querySelectorAll('[data-widget-group]').forEach(b=>b.onclick=()=>{group=b.dataset.widgetGroup;document.querySelectorAll('[data-widget-group]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));draw()});draw();}
function syncControl(){const last=connections.find(c=>c.provider==='whoop')?.last_synced_at;const detail=syncState.error?'Could not refresh. Select to retry.':syncState.inProgress?'Sync running in another tab':last?'Last WHOOP sync: '+new Date(last).toLocaleString(dateLocale,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):syncState.checkedAt?'Records updated '+new Date(syncState.checkedAt).toLocaleTimeString(dateLocale,{hour:'numeric',minute:'2-digit'}):'Refresh your records';return `<button class="icon-btn refresh-data ${syncState.busy?'is-syncing':''} ${syncState.error?'sync-retry':''}" data-action="refresh" aria-label="${syncState.error?'Retry refreshing data':'Refresh data'}" aria-describedby="sync-description" ${syncState.busy?'disabled':''} title="${esc(detail)}">${icon('refresh')}</button><span id="sync-description" class="sr-only" role="status">${syncState.busy?'Updating your connected data…':esc(detail)}</span>`;}
function updateSyncControl(){const host=$('#sync-control');if(host){host.innerHTML=syncControl();wire(host);}}
const syncController=createSyncController({loadConnections:async()=>{const s=await data.api('connections');return s.connections||[]},sync:()=>data.api('whoop-sync'),reload:async()=>{await refresh();if(data.user&&!boardDraft&&!$('#onboard-form')&&!chatOpen&&!['Nutrition','Journal'].includes(page))await render()},onState:state=>{if(!data.user)return;syncState={...syncState,...state};updateSyncControl();}});
async function refreshConnected(manual=false){const result=await syncController.run();if(manual)toast(result.ok?result.inProgress?'WHOOP sync is already running. Refresh again shortly.':result.live?result.cycles===true?'WHOOP readings refreshed':result.cycles===false?'Recovery and sleep refreshed. Reconnect WHOOP to add strain, calories and heart rate.':'Recovery and sleep refreshed. Strain, calories and heart rate aren’t in the WHOOP sync yet.':'Saved records refreshed. Manage sources to connect a wearable.':syncState.error||'Could not refresh. Your saved readings are still available.');}

// Callouts connect the body to its cards: on Home they carry the status, not a second copy of the number.
// The body measurements as markers on the figure, each joined by a thin line to its latest entry, or to an "Add" call to action.
const bodyDay=d=>new Date(d).toLocaleDateString(dateLocale,{timeZone:'UTC',month:'short',day:'numeric'});
function bodySignals(){return [['weight','upper'],['body_fat','middle'],['lean_mass','lower']].map(([kind,position])=>{const m=metrics.find(x=>x.kind===kind),r=reading(kind),name=m.name.toLowerCase();return r?`<button class="body-pin pin-${position}" data-metric="${kind}" aria-label="${esc(m.name)}: ${formatValue(r.value,kind)} ${m.unit}. Explore your ${name} trend"><span class="pin-dot"></span><span class="pin-line"></span><span class="pin-copy"><span class="pin-name">${esc(m.name)}<small>${bodyDay(r.observed_at)}</small></span><strong>${formatValue(r.value,kind)}<small>${m.unit}</small></strong></span></button>`:`<button class="body-pin pin-${position} is-empty" data-body-entry="${kind}" aria-label="Add ${name} measurement"><span class="pin-dot"></span><span class="pin-line"></span><span class="pin-copy"><span class="pin-name">${esc(m.name)}<small>Not added yet</small></span><span class="pin-add">${icon('plus')}Add</span></span></button>`}).join('')}
function portrait(signals=false){const image='<img class="human-portrait" src="/images/human-portrait.png" alt="Illustrative portrait of a curly-haired adult in soft natural light" width="1024" height="1536" fetchpriority="high">';return `<div class="portrait-scene ${signals?'portrait-anchored':''}">${signals?`<div class="portrait-figure">${image}${bodySignals()}</div>`:image}</div>`}
// Pointer-driven depth for the avatar; skipped for reduced motion and touch-only devices.
function bindDepth(root=app){if(matchMedia('(prefers-reduced-motion: reduce)').matches||!matchMedia('(hover: hover)').matches)return;root.querySelectorAll('.portrait-scene').forEach(scene=>{const figure=scene.querySelector('.portrait-figure,.human-portrait,.vitruvian-image');if(!figure)return;let frame=0;scene.onpointermove=e=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const r=scene.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;scene.classList.add('is-tilting');figure.style.setProperty('--tilt-y',(x*6).toFixed(2)+'deg');figure.style.setProperty('--tilt-x',(-y*4).toFixed(2)+'deg')})};scene.onpointerleave=()=>{cancelAnimationFrame(frame);scene.classList.remove('is-tilting');figure.style.removeProperty('--tilt-y');figure.style.removeProperty('--tilt-x')}})}
function hasRepresentation(){return profile?.representation==='digital'||profile?.representation==='photo'}
function vitruvianVisual(){const figure=digitalFigure(profile?.gender);return `<div class="portrait-scene portrait-anchored vitruvian-scene"><div class="portrait-figure vitruvian-figure"><img class="vitruvian-image" src="${figure.src}" alt="${figure.alt}" width="1024" height="1024">${bodySignals()}</div></div>`}
function personalVisual(){if(profile?.representation==='digital')return vitruvianVisual();if(portraitURL)return `<div class="portrait-scene portrait-anchored personal-portrait"><div class="portrait-figure"><img class="human-portrait" src="${esc(portraitURL)}" alt="Your personal AI portrait in the Xeyo style">${bodySignals()}</div></div>`;return portrait(true);}
function portraitStudio(){if(!profile?.photo_record_id||profile.representation!=='photo'){choosePortraitPhoto();return;}openPortraitStudio({sourceId:profile.photo_record_id,api:data.api,showModal,heading,closeModal,connect:()=>aiSettings(()=>portraitStudio()),changePhoto:choosePortraitPhoto,accepted:async()=>{await refresh();await render();toast('Your portrait is ready')}});}
function choosePortraitPhoto(){
 if(!profile){profileSetup();return;}
 showModal(`${heading('Start with a photo of you.','Your personal portrait')}<p>Choose a clear photo of yourself with your face and shoulders visible. We use it for your likeness and the original human for the portrait’s lighting and composition.</p><form id="portrait-photo-form"><label class="upload-zone" style="margin-top:24px">${icon('camera')}<span>Choose your photo</span><input type="file" name="photo" accept="image/*,.heic,.heif" required></label><p class="mini-note">JPG, PNG, WebP or HEIC · Resized on your device and stripped of location data · Stored privately. The photo is sent to OpenAI only when you choose Generate.</p><div id="form-error"></div><div class="dialog-footer"><span class="mini-note">Your likeness. Soft light. Bare shoulders.</span><button type="submit" class="btn">Continue to portrait studio ↗</button></div></form>`);
 $('#portrait-photo-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await data.saveProfile({...profile,representation:'photo'},e.target.elements.photo.files[0]);await refresh();closeModal();await render();portraitStudio();})};
}
function profileSetup(){
 mealLogger.cancel();const previous=profile?.photo_record_id;
 openOnboarding({app,profile,photos:records.filter(r=>r.kind==='photo'),orb,save:data.saveProfile,done:async saved=>{
  const photoChanged=saved?.representation==='photo'&&saved.photo_record_id&&saved.photo_record_id!==previous;
  if(saved){profile=saved;if(saved.photo_record_id!==previous)portraitURL=null;portraitChecked=Date.now();}
  page='Home';await render();window.scrollTo(0,0);
  // Setup is complete once the profile is confirmed. Background data failures belong
  // to the dashboard's refresh control, not to the onboarding save button.
  if(saved)void refreshConnected();
  if(photoChanged)portraitStudio();
 },signOut:actions.logout});
}

async function loadPeers(){try{peerResult=await data.peerPercentiles()}catch(e){peerResult={status:'error',message:e.message}}const host=$('#profile-peers');if(page==='Profile'&&host){host.innerHTML=peerPage(peerResult);wire(host);}}
function dataCallout(){return readings.length?'':`<section class="card data-callout"><div><h2>No measurements yet</h2><p>Connect WHOOP, or import Apple Health or Fitbit data. You can also look around with sample data first.</p></div><div class="actions"><button class="btn" data-nav="Integrations">Connect a source</button><button class="btn light" data-action="demo-on">Explore with sample data</button></div></section>`}
// Home: the numbers people check every day, each with its last two weeks underneath, on one screen.
const ownRows=kind=>{const r=reading(kind);return r?readings.filter(x=>x.kind===kind&&x.source===r.source&&x.unit===r.unit):[]};
const lastDays=(kind,days=14)=>dailyMeans(ownRows(kind),{days});
function cardHead(title,{nav,id,extra=''}={}){return `<div class="card-head"><span class="marker" aria-hidden="true"></span><h2 ${id?`id="${id}"`:''}>${title}</h2><span class="spacer"></span>${extra}${nav?`<button class="icon-btn small" data-nav="${nav}" aria-label="Open ${nav}">${icon('arrow')}</button>`:''}</div>`}
const deltaBadge=kind=>latestChange(ownRows(kind),reading(kind)).badge;
const shortDate=at=>new Date(at).toLocaleDateString(dateLocale,{month:'short',day:'numeric'});
// Amounts read best as bars from zero; vitals as a line in their own range.
const barKinds=new Set(['sleep','strain','energy_burned','steps','active_energy','recovery','sleep_performance','sleep_deep','sleep_rem','sleep_light','sleep_awake']);
// WHOOP cycle readings (strain, calories, heart rate) arrive only once the connection includes cycles.
const cycleKinds=new Set(['strain','energy_burned','heart_rate']);
// WHOOP's strain, calories and heart rate arrive with its daily cycles. The tile says which step is missing.
function tileEmpty(m){const whoop=connections.some(c=>c.provider==='whoop'),cycle=whoop&&cycleKinds.has(m.kind),name=esc(m.name);
 const [text,action]=!whoop?[`${name} appears once a connected source records it.`,'<button class="btn light small" data-nav="Integrations">Connect a source</button>']
  :!cycle?[`${name} appears once WHOOP records it.`,'']
  :syncState.cycles===false?[`${name} comes from WHOOP’s daily cycles. Reconnect WHOOP once to share them.`,'<button class="btn light small" data-action="whoop">Reconnect WHOOP</button>']
  :syncState.cycles===true?[`WHOOP hasn’t recorded ${name.toLowerCase()} for recent days yet.`,'']
  :[`${name} comes from WHOOP’s daily cycles, which Xeyo’s WHOOP sync doesn’t include yet. Recovery and sleep sync as usual.`,''];
 return `<div class="card-empty"><p>${text}</p>${action}</div>`}
function sleepStages(){const parts=[['sleep_deep','Deep','accent'],['sleep_rem','REM','violet'],['sleep_light','Light','green']].map(([k,label,tone])=>({label,tone,r:reading(k)})).filter(s=>s.r&&!staleDays(s.r));const sum=parts.reduce((s,p)=>s+Number(p.r.value),0);return parts.length&&sum?`<div class="stage-split" role="img" aria-label="${parts.map(p=>`${p.label} ${formatValue(p.r.value,'sleep')} hours`).join(', ')}">${parts.map(p=>`<i class="t-${p.tone}" style="flex:${Number(p.r.value)}"></i>`).join('')}</div><div class="legend">${parts.map(p=>`<span><i class="t-${p.tone}"></i>${p.label} ${formatValue(p.r.value,'sleep')} h</span>`).join('')}</div>`:''}
// A heart that beats at the reading's own rate.
const beat=bpm=>`<span class="beat" style="--beat:${(60/Math.min(200,Math.max(30,Number(bpm)||60))).toFixed(2)}s" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 20.5s-7.6-4.5-9.7-9.1C.8 8 2.9 4 6.8 4c2.2 0 3.7 1.2 5.2 3.1C13.5 5.2 15 4 17.2 4c3.9 0 6 4 4.5 7.4-2.1 4.6-9.7 9.1-9.7 9.1z"/></svg></span>`;
// One signal as a tile: name, change badge, the big number, when it was recorded, and its last 14 days. The first
// tile is the dark focal card, sleep sits on the forest gradient (the night) and heart rate on red.
function tile(kind,i,total){
 const m=metrics.find(x=>x.kind===kind),r=reading(kind),stale=r&&staleDays(r),days=lastDays(kind),focal=i===0;
 const tools=boardDraft?`<span class="tile-tools"><button class="icon-btn small" data-step-widget="${kind}" data-step="-1" aria-label="Move ${esc(m.name)} earlier" ${i===0?'disabled':''}>←</button><button class="icon-btn small" data-step-widget="${kind}" data-step="1" aria-label="Move ${esc(m.name)} later" ${i===total-1?'disabled':''}>→</button><button class="icon-btn small" data-remove-widget="${kind}" aria-label="Remove ${esc(m.name)}">${icon('close')}</button></span>`:`${r?deltaBadge(kind):''}<button class="icon-btn small" data-metric="${kind}" aria-label="Open ${esc(m.name)} details">${icon('arrow')}</button>`;
 const when=!r?'':stale?`Last recorded ${shortDate(r.observed_at)}`:m.group==='sleep'?'Last night':localDay(new Date(r.observed_at))===localDay()?'Today':shortDate(r.observed_at);
 const body=r?`<div class="stat"><b>${formatValue(r.value,kind)}</b>${m.unit?`<small>${esc(m.unit)}</small>`:kind==='strain'?'<small>/ 21</small>':''}${kind==='heart_rate'?beat(r.value):''}</div><span class="stat-caption">${when}</span>${kind==='sleep'&&!stale?sleepStages():''}${miniChart(days,{type:barKinds.has(kind)?'bars':'line',label:`${m.name}, last ${days.length} days`,format:v=>formatValue(v,kind)})}`:tileEmpty(m);
 const tone=kind==='heart_rate'?'pulse':focal?'dark':kind==='sleep'?'forest':'';
 return `<section class="card tile ${tone} ${stale?'is-stale':''}" aria-labelledby="tile-${kind}">${cardHead(esc(m.name),{id:'tile-'+kind,extra:tools})}${body}</section>`;
}
function addTile(){return `<button class="card tile tile-add" data-action="${boardDraft?'add-widgets':'edit-dashboard'}">${icon('plus')}<span>Add a signal</span></button>`}
// The month over the person's portrait: which of the last ten days have records, and where to go next.
function monthCard(){
 const now=new Date(),image=hasRepresentation()?portraitURL||(profile?.representation==='digital'?digitalFigure(profile?.gender).src:'/images/human-portrait.png'):null;
 const logged=new Set([...readings.map(r=>localDay(new Date(r.observed_at))),...journalData.map(e=>e.logged_on),...mealData.map(m=>m.created_at&&localDay(new Date(m.created_at)))]);
 const days=Array.from({length:10},(_,i)=>{const d=new Date(now);d.setDate(now.getDate()-9+i);return d});
 return `<section class="card month-card ${image?'':'no-image'}" aria-labelledby="month-title">${image?`<img class="month-figure" src="${esc(image)}" alt="">`:''}<div class="month-panel"><h2 id="month-title">${now.toLocaleDateString(dateLocale,{month:'long'})} <span>${now.getFullYear()}</span></h2><ol class="month-days">${days.map((d,i)=>{const has=logged.has(localDay(d));return `<li class="${has?'has-data':''} ${i===days.length-1?'today':''}" aria-label="${d.toLocaleDateString(dateLocale,{month:'short',day:'numeric'})}: ${has?'data recorded':'nothing recorded'}">${String(d.getDate()).padStart(2,'0')}</li>`}).join('')}</ol><div class="month-links">${[['Sleep goals','Sleep'],['Check-ins','Journal'],['Blood results','Blood records']].map(([t,n])=>`<button data-nav="${n}">${t}</button>`).join('')}</div></div></section>`;
}
// Calories: what the wearable says was burned today against what was logged as eaten.
function caloriesCard(){
 const burned=reading('energy_burned'),fresh=burned&&localDay(new Date(burned.observed_at))===localDay()?burned:null,t=totals(mealData),eaten=Math.round(t.calories),energy=t.protein*4+t.carbs*4+t.fat*9,share=k=>energy?Math.round(t[k]*(k==='fat'?9:4)/energy*100):0,n=mealData.length;
 const out=fresh?Math.round(Number(fresh.value)):null,balance=out!==null&&n?eaten-out:null;
 return `<section class="card calories-card" aria-labelledby="calories-title">${cardHead('Calories',{id:'calories-title',nav:'Nutrition'})}<div class="calorie-pair"><div><span class="stat-caption">Eaten</span><div class="stat"><b>${eaten.toLocaleString(dateLocale)}</b><small>kcal</small></div></div><div><span class="stat-caption">Burned</span><div class="stat"><b>${out!==null?out.toLocaleString(dateLocale):'—'}</b><small>kcal</small></div></div></div>${out!==null&&n?`<div class="calorie-bar" role="img" aria-label="Eaten ${eaten} of ${out} kcal burned"><i style="width:${Math.min(100,Math.round(eaten/out*100))}%"></i></div><span class="stat-caption">${balance<0?`${Math.abs(balance).toLocaleString(dateLocale)} kcal under what you burned`:`${balance.toLocaleString(dateLocale)} kcal over what you burned`}</span>`:`<span class="stat-caption">${n?`${n} ${n===1?'meal':'meals'} logged today`:'Nothing logged today'}${out===null?' · burned calories appear with WHOOP cycles':''}</span>`}${energy?`<div class="legend macro-legend">${[['protein','Protein','accent'],['carbs','Carbs','violet'],['fat','Fat','blue']].map(([k,l,tone])=>`<span><i class="t-${tone}"></i>${l} ${Math.round(t[k])} g · ${share(k)}%</span>`).join('')}</div>`:`<button class="btn light small" data-nav="Nutrition">Log a meal</button>`}</section>`;
}
// Weight: the latest entry, and a ruler to log today's without leaving Home.
function weightCard(){
 const w=reading('weight'),prev=readings.filter(x=>x.kind==='weight'&&x.unit===w?.unit)[1],change=w&&prev?Number(w.value)-Number(prev.value):null;
 return `<section class="card weight-card" aria-labelledby="weight-title">${cardHead('Weight',{id:'weight-title',nav:'Body',extra:change!==null&&Math.abs(change)>=.05?`<span class="badge quiet" title="Since ${bodyDay(prev.observed_at)}">${change>0?'↑':'↓'} ${Math.abs(change).toFixed(1)} kg</span>`:''})}<span class="stat-caption">${w?`Last entry ${formatValue(w.value,'weight')} kg · ${bodyDay(w.observed_at)}`:'No entry yet'}</span><form id="home-weight" class="weight-form">${rulerField({kind:'weight',name:'value',value:w?Number(w.value):null,unit:'kg',id:'home-weight-value'})}<button class="btn small" type="submit">Save today</button></form></section>`;
}
// Notable changes against the person's own days, the week in summary, and today's check-in.
// The last seven days side by side: the day's recovery, sleep and strain (the first three with data this week),
// and the mood from that day's check-in. Today's column is the one in the accent.
function weekCard(){
 const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {key:localDay(d),date:d}}),today=localDay();
 const perDay=kind=>{const map=new Map();for(const r of ownRows(kind)){const v=Number(r.value);if(!Number.isFinite(v))continue;const k=localDay(new Date(r.observed_at)),list=map.get(k)||[];list.push(v);map.set(k,list)}return new Map([...map].map(([k,l])=>[k,l.reduce((s,n)=>s+n,0)/l.length]))};
 const rows=['recovery','sleep','strain','hrv','resting_hr'].map(kind=>({kind,m:metrics.find(x=>x.kind===kind),values:perDay(kind)})).filter(r=>r.m&&days.some(d=>r.values.has(d.key))).slice(0,3);
 const mood=new Map(journalData.map(e=>[e.logged_on,e])),checked=mood.has(today);
 const cell=(row,d)=>{const v=row.values.get(d.key);if(v==null)return `<td class="${d.key===today?'is-today':''}"><span class="week-none" aria-label="No reading">–</span></td>`;const max=Math.max(...row.values.values(),row.kind==='recovery'?100:0);return `<td class="${d.key===today?'is-today':''}"><b>${formatValue(v,row.kind)}</b><i style="width:${Math.max(8,Math.round(v/max*100))}%"></i></td>`};
 const moodCell=d=>{const e=mood.get(d.key),name=moods.find(([id])=>id===e?.mood)?.[1];return `<td class="${d.key===today?'is-today':''}">${e?`<span class="week-mood">${name?esc(name):'Note'}</span>`:d.key===today?`<button class="week-add" data-nav="Journal" aria-label="Check in for today">${icon('plus')}</button>`:'<span class="week-none" aria-label="No check-in">–</span>'}</td>`};
 const head=`<tr><th scope="col"><span class="sr-only">Signal</span></th>${days.map(d=>`<th scope="col" class="${d.key===today?'is-today':''}">${d.date.toLocaleDateString(dateLocale,{weekday:'short'})}<small>${d.date.getDate()}</small>${d.key===today?'<span class="sr-only">, today</span>':''}</th>`).join('')}</tr>`;
 const body=rows.map(r=>`<tr><th scope="row"><button class="week-signal" data-metric="${r.kind}">${esc(r.m.name)}${r.m.unit?` <small>${esc(r.m.unit==='hours'?'h':r.m.unit)}</small>`:''}</button></th>${days.map(d=>cell(r,d)).join('')}</tr>`).join('')+`<tr><th scope="row"><button class="week-signal" data-nav="Journal">Mood</button></th>${days.map(moodCell).join('')}</tr>`;
 return `<section class="card week-card" aria-labelledby="week-title">${cardHead('Your week',{id:'week-title',extra:`<button class="text-button" data-action="weekly">Summary</button><button class="chip ${checked?'':'is-cta'}" data-nav="Journal">${checked?'Checked in today':'Check in'}</button>`})}<table class="week-table">${head}${body}</table></section>`;
}
function home(){
 if(!readings.length&&!boardDraft)return `<div class="home-empty card dark">${cardHead('Your health, in perspective')}<p>No measurements yet. Connect WHOOP, or import Apple Health or Fitbit data. You can also look around with sample data first.</p><div class="actions"><button class="btn accent" data-nav="Integrations">Connect a source</button><button class="btn light" data-action="demo-on">Explore with sample data</button></div></div>`;
 const list=currentBoard().widgets.map(w=>w.id),slots=Array.from({length:BOARD_LIMIT-list.length},addTile).join('');
 return `<div class="home-grid ${boardDraft?'board-editing':''}">${list.map((k,i)=>tile(k,i,list.length)).join('')}${slots}${monthCard()}${caloriesCard()}${weightCard()}${weekCard()}</div>`;
}

// Nutrition: the meal composer beside the day's balance (energy and each macro's share of it) and its food journal.
function nutrition(){
 const t=totals(mealData),energy=t.protein*4+t.carbs*4+t.fat*9,share=k=>energy?Math.round(t[k]*(k==='fat'?9:4)/energy*100):0,n=mealData.length,today=nutritionDay===localDay(),day=new Date(nutritionDay+'T12:00:00').toLocaleDateString(dateLocale,{month:'short',day:'numeric'});
 const balance=`<section class="card dark nutrition-balance" aria-labelledby="balance-title">${cardHead(`Daily balance <span class="muted">· ${n} ${n===1?'entry':'entries'}</span>`,{id:'balance-title'})}<div class="stat"><b>${Math.round(t.calories).toLocaleString(dateLocale)}</b><small>/kcal</small></div><span class="stat-caption">${today?'Today':day} · estimated from your logged meals</span><div class="balance-macros">${[['protein','Protein','accent'],['carbs','Carbs','violet'],['fat','Fat','blue']].map(([k,label,tone])=>`<div class="balance-macro">${dotShare(share(k),{cols:6,rows:4,tone,px:8})}<span><b>${Math.round(t[k])}<small> g</small></b><small>${label} · ${share(k)}%</small></span></div>`).join('')}</div></section>`;
 const meals=n?`<ul class="meal-list" tabindex="0" aria-label="Meals for ${esc(day)}">${mealData.map(m=>`<li class="meal-row"><span class="meal-icon">${icon('food')}</span><span class="meal-copy"><b>${esc(m.name)}</b><small>${esc(m.meal_type)} · ${Math.round(m.protein)} g protein</small></span><span class="meal-kcal"><b>${Math.round(m.calories)}</b><small>kcal</small></span><button class="icon-btn small" data-delete-meal="${m.id}" aria-label="Delete ${esc(m.name)}">${icon('trash')}</button></li>`).join('')}</ul>`:`<div class="card-empty"><p>Your meals for ${today?'today':esc(day)} will appear here.</p>${capabilities.mealAnalysis?button('Describe a meal','meal','light small'):button('Add a meal','meal-manual','light small')}</div>`;
 return `<div class="nutrition-grid"><section class="card nutrition-composer ${n?'has-meals':''}" aria-labelledby="meal-chat-title"><div id="nutrition-chat-host"></div></section>${balance}<section class="card nutrition-log" aria-labelledby="log-title">${cardHead(`Food journal <span class="muted">· ${esc(day)}</span>`,{id:'log-title'})}${meals}</section></div>`;
}

// One white card per body measurement: the latest entry as a light number, its change, and the entries so far as a thin line.
// Measurements you have entered get a card each; the ones you haven't are compact "Add" rows (one empty-state card when there are none yet).
function bodyCards(){const kinds=metrics.filter(m=>m.group==='body'),have=kinds.filter(m=>reading(m.kind)),missing=kinds.filter(m=>!reading(m.kind));
 const cards=have.map(m=>{const r=reading(m.kind),name=m.name.toLowerCase(),rows=readings.filter(x=>x.kind===m.kind&&x.source===r.source&&x.unit===r.unit).sort((a,b)=>Date.parse(a.observed_at)-Date.parse(b.observed_at)).slice(-12),change=rows.length>1?Number(r.value)-Number(rows.at(-2).value):null;return `<article class="card body-measure" aria-labelledby="measure-${m.kind}">${cardHead(esc(m.name),{id:'measure-'+m.kind,extra:`<button class="icon-btn small" data-metric="${m.kind}" aria-label="Explore your ${name} trend">${icon('arrow')}</button>`})}<div class="stat"><b>${formatValue(r.value,m.kind)}</b><small>${m.unit}</small>${change!==null&&Math.abs(change)>=.05?`<span class="badge quiet">${change>0?'↑':'↓'} ${formatValue(Math.abs(change),m.kind)}</span>`:''}</div><span class="stat-caption">${esc(r.source)} · ${bodyDay(r.observed_at)}</span>${rows.length>1?`<div class="measure-history"><div class="measure-line" role="img" aria-label="${esc(m.name)}, last ${rows.length} entries">${sparkline(rows.map(x=>Number(x.value)),{tone:'accent'})}${(()=>{const v=rows.map(x=>Number(x.value)),lo=Math.min(...v),hi=Math.max(...v);return v.map((n,i)=>`<i style="left:${(i/(v.length-1)*100).toFixed(1)}%;top:${(90-(hi>lo?(n-lo)/(hi-lo):.5)*80).toFixed(1)}%"></i>`).join('')})()}</div><span>${rows.length} entries since ${bodyDay(rows[0].observed_at)}</span></div>`:''}<div class="measure-action"><span>Add a new entry</span><button class="icon-btn small" data-body-entry="${m.kind}" aria-label="Add ${name} measurement">${icon('plus')}</button></div></article>`}).join('');
 const rows=`<ul class="measure-add-list">${missing.map(m=>`<li><button class="measure-add" data-body-entry="${m.kind}" aria-label="Add ${m.name.toLowerCase()} measurement"><span class="measure-add-name">${esc(m.name)}<small>${m.unit}</small></span><span class="measure-add-cta">${icon('plus')}Add</span></button></li>`).join('')}</ul>`;
 const add=!missing.length?'':have.length?`<section class="card body-add" aria-labelledby="body-add-title">${cardHead('Add a measurement',{id:'body-add-title'})}${rows}</section>`:`<section class="card body-add is-first" aria-labelledby="body-add-title">${cardHead('Add your first measurement',{id:'body-add-title'})}<p>Weight, body fat or lean mass, from a scale, a scan or your own records. Each entry keeps its date, so you can follow changes over time. No wearable needed.</p>${rows}</section>`;
 // What a wearable measures about the body sits beside the measurements you enter, as the same tiles as Home.
 // The last tile widens to finish its row: beside the portrait the first four cards fill two columns, then rows of four.
 const signals=['resting_hr','hrv','spo2','skin_temperature','respiratory_rate','energy_burned','active_energy','steps'].filter(k=>metrics.some(m=>m.kind===k)&&reading(k));
 const shown=hasRepresentation(),fullAdd=!shown&&add&&!have.length,count=have.length+(add&&!fullAdd?1:0)+signals.length,left=(shown?Math.max(0,count-4):count)%4;
 return `<div class="body-side">${cards}${add}${signals.map((k,i)=>{const html=tile(k,1,2);return i===signals.length-1&&left?html.replace('class="card tile ',`class="card tile span-${5-left} `):html}).join('')}</div>`}
function body(){const shown=hasRepresentation(),digital=profile?.representation==='digital';return `<div class="body-page ${shown?'':'stats-only'}">${shown?`<section class="card body-visual ${digital?'is-digital':'is-portrait'}" aria-labelledby="body-visual-title">${cardHead('Your body',{id:'body-visual-title'})}${personalVisual()}<div class="body-visual-foot"><span class="body-visual-note">${digital?digitalFigure(profile.gender).label+' · Illustrative artwork':portraitURL?'Your AI portrait':'Illustrative portrait'} · Not a body composition scan</span>${digital?'':'<button class="btn light small" data-action="portrait-studio">Personalise my portrait ↗</button>'}</div></section>`:''}${bodyCards()}</div>`}
function bodyEntry(kind){openBodyMeasurement({kind,readings,save:data.saveBodyMeasurement,remove:data.removeBodyMeasurement,onChanged:async()=>{try{await refresh();await render();toast('Measurements updated')}catch{toast('Saved. Refresh to see the latest numbers.')}},showModal,heading,closeModal,openTrend:metricDetail})}
const dayLabel=day=>esc(new Date(day+'T12:00:00').toLocaleDateString(dateLocale,{year:'numeric',month:'short',day:'numeric'}));
// Results are grouped by test and unit (values in different units are never compared), newest first.
function labGroups(){const groups=new Map();for(const r of [...labResults].sort((a,b)=>b.collected_on.localeCompare(a.collected_on))){const key=r.marker.toLowerCase()+'|'+r.unit;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)}return [...groups.values()].map(rows=>[rows[0],rows[1],rows.length])}
// Where the value sits against the laboratory's range: the band is the reference, the dot the result.
const labOut=r=>['Above reference','Below reference'].includes(labRangeStatus(r));
function rangeBar(r){const low=r.reference_low,high=r.reference_high,text=`${low??'—'} – ${high??'—'}`;if(low==null||high==null||high<=low)return `<span class="range"><span class="range-text">${text}</span></span>`;const pad=(high-low)/2,pos=Math.max(0,Math.min(100,(Number(r.value)-(low-pad))/(2*(high-low))*100));return `<span class="range"><span class="range-bar ${labOut(r)?'out':''}" role="img" aria-label="${esc(r.value)} against a reference of ${text}"><i class="range-band"></i><b style="left:${pos.toFixed(1)}%"></b></span><span class="range-text">${text}</span></span>`}
// History over time: shaded reference band, results outside it marked.
function labChart(history,r){if(history.length<2)return '<div class="lab-chart-empty">One result so far. Add the next one to see how it changes.</div>';const low=r.reference_low,high=r.reference_high,values=history.map(x=>Number(x.value)).concat([low,high].filter(v=>v!=null).map(Number)),min=Math.min(...values),max=Math.max(...values),span=max-min||1,y=v=>(88-(Number(v)-min)/span*76).toFixed(2),start=Date.parse(history[0].collected_on),dur=Date.parse(history.at(-1).collected_on)-start||1,x=d=>(5+(Date.parse(d)-start)/dur*90).toFixed(2);const band=low!=null&&high!=null?`<rect class="lab-band" x="0" width="100" y="${y(high)}" height="${(y(low)-y(high)).toFixed(2)}"/>`:'',edges=[low,high].filter(v=>v!=null).map(v=>`<line class="lab-edge" x1="0" x2="100" y1="${y(v)}" y2="${y(v)}"/>`).join(''),limits=[low,high].filter(v=>v!=null).map(v=>`<span class="lab-limit" style="top:${y(v)}%">${esc(v)}</span>`).join('');return `<div class="lab-chart" role="img" aria-label="${history.length} results over time, from ${esc(history[0].value)} to ${esc(history.at(-1).value)} ${esc(r.unit)}"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${band}${edges}<polyline points="${history.map(h=>`${x(h.collected_on)},${y(h.value)}`).join(' ')}"/></svg>${limits}${history.map(h=>`<i class="${labOut(h)?'out':''}" style="left:${x(h.collected_on)}%;top:${y(h.value)}%" title="${esc(h.collected_on)}: ${esc(h.value)} ${esc(h.unit)} · ${labRangeStatus(h)}">${history.length<=8?`<span>${esc(h.value)}</span>`:''}</i>`).join('')}</div>`}
function labChange(r,previous){if(!previous)return '<span class="lab-change same">First result</span>';const diff=Number(r.value)-Number(previous.value);return `<span class="lab-change ${diff?'':'same'}">${diff>0?'↑':diff<0?'↓':'='} ${Math.abs(diff).toLocaleString(dateLocale,{maximumFractionDigits:2})}<small>since ${dayLabel(previous.collected_on)}</small></span>`}
// A private file row (lab report or reference photo): icon, name, date, open and delete.
const recordRow=r=>`<li class="record-row"><span class="record-icon">${icon(r.kind==='photo'?'camera':'report')}</span><span class="record-name"><b>${esc(r.name)}</b><small>${r.kind==='photo'?'Reference photo':'Lab report'} · ${new Date(r.created_at).toLocaleDateString(dateLocale,{year:'numeric',month:'short',day:'numeric'})}</small></span><button class="icon-btn small" data-download="${r.id}" aria-label="Open ${esc(r.name)}">${icon('arrow')}</button><button class="icon-btn small delete-button" data-delete-record="${r.id}" aria-label="Delete ${esc(r.name)}">${icon('trash')}</button></li>`;
function reports(){const labFiles=records.filter(r=>r.kind==='lab'),groups=labGroups();return `<div class="labs-grid"><section class="panel labs-results" aria-labelledby="labs-title">${cardHead('Blood results',{id:'labs-title',extra:labResults.length?`<span class="chip">${groups.length} ${groups.length===1?'test':'tests'} · ${labResults.length} ${labResults.length===1?'result':'results'}</span>`:''})}${labResults.length?`<div class="labs-table-wrap"><table class="lab-table"><thead><tr><th scope="col">Test</th><th scope="col">Result</th><th scope="col">Change</th><th scope="col">Lab reference</th><th scope="col">Status</th><th scope="col"><span class="sr-only">History</span></th></tr></thead><tbody>${groups.map(([r,previous,count])=>`<tr class="${labOut(r)?'is-out':''}"><td class="lab-test"><button class="lab-name" data-lab="${r.id}">${esc(r.marker)}</button><small>${dayLabel(r.collected_on)}${r.laboratory?' · '+esc(r.laboratory):''}${count>1?` · ${count} results`:''}</small></td><td class="lab-value"><b>${esc(r.value)}</b><small>${esc(r.unit)}</small></td><td class="lab-delta">${labChange(r,previous)}</td><td class="lab-range">${rangeBar(r)}</td><td class="lab-state"><span class="chip lab-status ${labOut(r)?'out':''}">${labRangeStatus(r)}</span></td><td class="lab-open"><button class="icon-btn small" data-lab="${r.id}" aria-label="View ${esc(r.marker)} history">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="card-empty"><p>Your results, over time. Add the value, unit and reference range exactly as printed by your laboratory.</p>${button(icon('plus')+'Add a blood result','lab')}</div>`}<p class="labs-note">Reference flags compare your entry with the range you provide. They are not a diagnosis. Values in different units are kept separate.</p></section><section class="panel labs-docs" aria-labelledby="docs-title">${cardHead('Lab documents',{id:'docs-title',extra:labFiles.length?`<span class="chip">${labFiles.length} ${labFiles.length===1?'file':'files'}</span>`:''})}${labFiles.length?`<ul class="record-list">${labFiles.map(recordRow).join('')}</ul>`:`<div class="card-empty"><p>A home for your health history. Upload a PDF or image of a report; only your account can access it.</p>${button(icon('upload')+'Upload a report','upload','light')}</div>`}</section></div>`}
function labForm(row={}){showModal(`${heading(row.id?'Edit blood result':'Add a blood result','Health records')}<p>Copy the numeric value and unit exactly from your laboratory report.</p><form id="lab-form" style="margin-top:22px"><div class="form-grid"><label class="field">Test name<input name="marker" required maxlength="120" placeholder="e.g. Ferritin" value="${esc(row.marker||'')}"></label><label class="field">Collection date<input name="collected_on" type="date" required max="${localDay()}" value="${row.collected_on||localDay()}"></label><label class="field">Result<input name="value" type="number" required min="-1000000000" max="1000000000" step="any" value="${row.value??''}"></label><label class="field">Unit<input name="unit" required maxlength="40" placeholder="e.g. ng/mL" value="${esc(row.unit||'')}"></label><label class="field">Lower reference limit (optional)<input name="reference_low" type="number" step="any" value="${row.reference_low??''}"></label><label class="field">Upper reference limit (optional)<input name="reference_high" type="number" step="any" value="${row.reference_high??''}"></label></div><label class="field">Laboratory (optional)<input name="laboratory" maxlength="160" value="${esc(row.laboratory||'')}"></label><label class="field">Notes (optional)<textarea name="notes" maxlength="2000">${esc(row.notes||'')}</textarea></label><div id="form-error"></div><div class="dialog-footer"><p>Saved privately to your account.</p><button class="btn" type="submit">Save result</button></div></form>`);$('#lab-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await data.saveLabResult(Object.fromEntries(new FormData(e.target)),row.id);await refresh();closeModal();page='Blood records';await render();toast('Blood result saved')})}}
function labDetail(id){const r=labResults.find(r=>r.id===id);if(!r)return;const history=labResults.filter(x=>x.marker.toLowerCase()===r.marker.toLowerCase()&&x.unit===r.unit).sort((a,b)=>a.collected_on.localeCompare(b.collected_on));showModal(`${heading(esc(r.marker),'Blood results · '+esc(r.laboratory||'Your report'))}<p>${dayLabel(r.collected_on)} · Entered from your laboratory report</p><div class="lab-detail-top"><div class="stat"><b>${esc(r.value)}</b><small>${esc(r.unit)}</small></div><span class="chip lab-status ${labOut(r)?'out':''}">${labRangeStatus(r)}</span></div><div class="lab-detail-range"><span>Laboratory reference</span>${rangeBar(r)}</div><div class="lab-history"><div class="lab-history-head"><h3>History</h3><span class="legend"><span><i class="lab-key-band"></i>Reference range</span><span><i class="t-accent"></i>Outside the range</span></span></div>${labChart(history,r)}${history.length>1?`<div class="lab-axis"><span>${dayLabel(history[0].collected_on)}</span><span>${dayLabel(history.at(-1).collected_on)}</span></div>`:''}</div><p class="mini-note">${history.length} ${history.length===1?'result':'results'} in ${esc(r.unit)}. Reference ranges may change between laboratories.</p>${r.notes?`<p class="lab-notes">${esc(r.notes)}</p>`:''}<div class="dialog-footer"><button class="btn light" id="edit-lab">Edit result</button><button class="text-button" id="delete-lab">Delete result</button></div>`);$('#edit-lab').onclick=()=>labForm(r);$('#delete-lab').onclick=()=>{showModal(`${heading('Delete this blood result?')}<p>This permanently removes ${esc(r.marker)} collected on ${esc(r.collected_on)}.</p><div class="dialog-footer">${button('Keep result','close','light')}<button class="btn" id="confirm-lab-delete">Delete result</button></div>`);$('#confirm-lab-delete').onclick=async()=>{try{$('#confirm-lab-delete').disabled=true;await data.removeLabResult(id);await refresh();closeModal();await render();toast('Result deleted')}catch(e){err(e)}}}}
function importWearable(provider){openWearableImport(provider,{showModal,heading,icon,api:data.api,done:async count=>{closeModal();await refresh();await render();toast(count+' measurements imported')}})}

// One card per source: what it brings, its status as a chip, and what you can do with it. WHOOP, the live connection, is the focal dark card.
function sourceCard({logo,name,mode,status,tone='',body,meta='',actions,cls=''}){return `<section class="card source-card ${cls}" aria-labelledby="source-${logo}"><div class="source-head"><span class="source-logo" aria-hidden="true">${logo==='apple'?'⌘':logo.slice(0,1).toUpperCase()}</span><span class="source-name"><h2 id="source-${logo}">${name}</h2><small>${mode}</small></span><span class="chip source-status ${tone}">${status}</span></div><p>${body}</p>${meta}<div class="source-actions">${actions}</div></section>`}
function integrations(){const whoop=connections.find(c=>c.provider==='whoop'),imported=prefix=>readings.some(r=>r.source.startsWith(prefix));return `${connectionError?`<div class="error sources-error"><span>Could not check connection status: ${esc(connectionError)}</span>${button('Try again','refresh','light small')}</div>`:''}<div class="sources-grid">${sourceCard({logo:'whoop',name:'WHOOP',mode:'Automatic sync',cls:'dark',status:whoop?'Connected':capabilities.whoop?'Ready to connect':'Activation pending',tone:whoop?'live':capabilities.whoop?'':'pending',body:'Recovery, sleep, resting heart rate, HRV, blood oxygen and respiratory rate. Includes skin temperature, sleep stages, efficiency and consistency. Imports up to 90 days.',meta:whoop?`<p class="source-meta">${whoop.last_synced_at?'Last synced '+new Date(whoop.last_synced_at).toLocaleString(dateLocale,{dateStyle:'medium',timeStyle:'short'}):'First synchronization pending'}</p>`:'',actions:whoop?button(icon('refresh')+'Sync now','sync-whoop','light')+button('Disconnect','disconnect-whoop','ghost'):capabilities.whoop?button('Connect WHOOP','whoop','accent'):'<p class="source-meta">WHOOP authorization is being configured. Connecting will become available here when activated.</p>'})}${sourceCard({logo:'apple',name:'Apple Watch / Health',mode:'File import',status:imported('Apple Health import')?'Data imported':'File import available',tone:imported('Apple Health import')?'done':'',body:'Import Apple Watch sleep stages, heart rate, HRV, blood oxygen, breathing, wrist temperature, steps and activity-ring energy, plus scale measurements, from your iPhone Health export. Exports of any size work.',meta:'<p class="source-meta">Automatic sync needs an iPhone companion app.</p>',actions:button(icon('upload')+'Import Apple Health','import-apple','light')})}${sourceCard({logo:'google',name:'Fitbit / Google Health',mode:'File import',status:imported('Fitbit import')?'Data imported':'File import available',tone:imported('Fitbit import')?'done':'',body:'Import recorded heart rate, sleep, HRV, weight and body-fat measurements from your data export.',meta:'<p class="source-meta">Automatic sync needs an approved Google Health app.</p>',actions:button(icon('upload')+'Import Fitbit data','import-fitbit','light')})}</div><section class="panel sources-note"><h3>Measured. Always clear.</h3><p>Every reading keeps its source and date. Disconnecting stops access; previously imported measurements stay in your records. Nutrition logs do not measure glucose, inflammation or water retention.</p></section>`}
// Profile: settings as rows, private reference photos beside them, the age-group comparison below.
function settingsRow(title,text,actions){return `<div class="profile-row"><div class="profile-row-copy"><h3>${title}</h3><p>${text}</p></div><div class="profile-row-actions">${actions}</div></div>`}
function settings(){const photos=records.filter(r=>r.kind==='photo'),ai=capabilities.chatAI,personal=capabilities.personalAI||ai?.provider==='openai',image=hasRepresentation()?portraitURL||(profile.representation==='digital'?digitalFigure(profile.gender).src:'/images/human-portrait.png'):null;return `<div class="profile-grid"><section class="panel profile-settings" aria-labelledby="settings-title">${cardHead('Settings',{id:'settings-title'})}${settingsRow(`Chat & reflections <span class="chip profile-state ${ai?'on':''}">${ai?esc(providerName(ai.provider)):'Not set up'}</span>`,ai?esc(providerName(ai.provider))+' · '+esc(ai.model)+'. Powers Ask Xeyo and journal reflections.':capabilities.personalAI?'Ask Xeyo needs a chat AI. Until you connect one, journal reflections use your OpenAI key.':'Connect ChatGPT, Claude, Gemini, Grok, Mistral, DeepSeek, Groq or OpenRouter with your own API key for Ask Xeyo, journal reflections and meal analysis.',`<button class="btn ${ai?'light':''}" data-action="chat-connect">${ai?'Manage chat AI':'Connect a chat AI'}</button>`)}${settingsRow(`Portraits & voice <span class="chip profile-state ${personal?'on':''}">${personal?'OpenAI':'Not set up'}</span>`,capabilities.personalAI?'Your OpenAI key creates your portrait, transcribes voice notes and analyses meals.':personal?'Covered by your OpenAI chat connection.':'Add your own OpenAI key to create your portrait and transcribe voice notes.',`<button class="btn light" data-action="ai-settings">${capabilities.personalAI?'Manage key':'Add OpenAI key'}</button>`)}${settingsRow('Account',esc(data.user.email),'<span class="chip profile-state on">Signed in</span>')}${settingsRow('Connected sources','Manage what comes into your health profile.','<button class="btn light" data-nav="Integrations">Manage sources</button>')}${settingsRow('Export your data','Download your complete meal history, readings, lab results and file metadata. CSV opens in any spreadsheet.',button(icon('download')+'CSV','export-csv','light')+button(icon('download')+'JSON','export','light'))}${settingsRow('Privacy & data use','Understand how files, food descriptions and recordings are handled.',button('Read details','privacy','light'))}${settingsRow('Sign out','End your session on this device.',button('Sign out','logout','light'))}</section><section class="card profile-view ${image?'':'no-image'}" aria-labelledby="view-title">${image?`<img class="profile-view-figure" src="${esc(image)}" alt="">`:''}<div class="profile-view-panel"><span class="profile-view-label">Profile & view</span><h2 id="view-title">${profile?esc(({photo:"Personal portrait",digital:digitalFigure(profile?.gender).label,stats:"Statistics only"})[profile.representation]):"Personalize your workspace"}</h2><p>${profile?profile.age+' years · ':''}Peer comparisons ${profile?.peer_opt_in?"enabled":"off"}. Change your image, age or participation anytime.</p><div class="profile-view-actions">${button("Edit preferences","profile-settings","light small")}${profile?.representation==='photo'?button("Portrait studio","portrait-studio","glass small"):''}</div></div></section><section class="panel profile-photos" aria-labelledby="photos-title">${cardHead('Portrait photos',{id:'photos-title',extra:`<span class="chip">${photos.length} ${photos.length===1?'file':'files'}</span>`})}<p class="profile-section-lead">Private reference photos for your portrait, kept apart from blood records.</p>${photos.length?`<ul class="record-list">${photos.map(recordRow).join('')}</ul>`:'<p class="profile-empty">No reference photos yet. The photo you choose for your portrait appears here.</p>'}</section><section class="panel profile-peers" aria-labelledby="peers-title">${cardHead('Age-group comparison',{id:'peers-title',extra:'<span class="chip">Private to you</span>'})}<div id="profile-peers">${peerPage(peerResult)}</div></section></div>`}
async function refresh(){const owner=data.user?.id;if(!owner)return;const next=await Promise.all([data.meals(nutritionDay),data.readings(),data.records(),data.labResults(),data.profile()]);if(data.user?.id!==owner)return;[mealData,readings,records,labResults,profile]=next;if(readings.length)setDemo(false);demo=!readings.length&&demoWanted();if(demo)readings=demoReadings();portraitURL=await data.profilePhoto(profile);portraitChecked=Date.now();try{journalData=await data.journalEntries();journalError=''}catch(e){journalError=e.message}peerResult=null;connections=[];connectionError='';try{const status=await data.api('connections');if(data.user?.id!==owner)return;connections=status.connections||[];capabilities=status.capabilities||{}}catch(e){connectionError=e.message}}

// One header per page: its title, a line of page-specific context and the page's own actions.
// The source most of the last 30 days came from, named once in the page lead instead of on every card.
function mainSource(){const since=Date.now()-30*86400000,count=new Map();for(const r of readings)if(Date.parse(r.observed_at)>=since)count.set(r.source,(count.get(r.source)||0)+1);return [...count].sort((a,b)=>b[1]-a[1])[0]?.[0]||''}
function pageLead(){const signals=metrics.filter(m=>m.group!=='sleep'&&m.group!=='body'&&reading(m.kind)).length,night=reading('sleep');return ({Vitals:signals?`${signals} ${signals===1?'signal':'signals'} from ${esc(mainSource()||'your connected sources')} · compared with your own recent days.`:'Connect a source to see your signals.',Sleep:night?'Your last recorded night · '+new Date(night.observed_at).toLocaleDateString(dateLocale,{weekday:'long',month:'long',day:'numeric'})+' · from '+esc(night.source):'Connect a wearable to see your sleep.',Body:'Measurements you add. Progress you can see.',Nutrition:'A conversation about what nourishes you.',Journal:'Private check-ins that connect your day to your data.','Blood records':'Blood results and original reports, saved to your private account.',Integrations:'Your account. Your measurements. Your choice.',Profile:'Your preferences, AI connections and data.'})[page]||''}
function pageActions(){if(page==='Vitals'||page==='Sleep')return `<button class="btn light" data-nav="Integrations">Manage sources ${icon('arrow')}</button>`;if(page==='Body')return `<button class="btn light" data-action="profile-settings">Change view ${icon('arrow')}</button>`;if(page==='Blood records')return button(icon('plus')+'<span>Add blood result</span>','lab')+button(icon('upload')+'<span>Upload report</span>','upload','light');if(page==='Nutrition')return `<label class="nutrition-day-control"><span>Viewing</span><input aria-label="Nutrition day" id="nutrition-day" type="date" max="${localDay()}" value="${nutritionDay}"></label>`+button(icon('plus')+'<span>Add manually</span>','meal-manual','light');return ''}
function accountMenu(name){return `<details class="account-menu"><summary class="icon-btn" aria-label="Account menu">${icon('menu')}</summary><div class="account-popover"><div class="who"><span class="avatar-letter">${esc(name.slice(0,1).toUpperCase())}</span><span><b>${esc(name)}</b><small>${esc(data.user?.email||'')}</small></span></div><button data-nav="Profile">${icon('body')} Profile</button><button data-nav="Integrations">${icon('link')} Integrations</button><button data-action="privacy">${icon('shield')} Privacy & data</button><button class="account-signout" data-action="logout">${icon('logout')} Sign out</button></div></details>`}
function chatDock(){return `<div id="chat-dock" class="chat-dock ${chatOpen?'is-open':''}">${chatOpen?'<div class="chat-scrim" data-action="close-chat" aria-hidden="true"></div>':''}<section class="chat-window" aria-label="Ask Xeyo" ${chatOpen?'':'hidden'}><div class="chat-window-bar"><span>${orb()} Ask Xeyo</span><button class="icon-btn small" data-action="close-chat" aria-label="Close Ask Xeyo">${icon('close')}</button></div><div id="chatbot-host"></div></section></div>`}
