function showModal(html,wide=false){if(!$('#modal').contains(document.activeElement))lastFocus=document.activeElement;$('#modal').innerHTML=`<section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><button class="icon-btn close" data-action="close" aria-label="Close">${icon('close')}</button>${html}</section>`;$('#modal').hidden=false;document.body.style.overflow='hidden';wire($('#modal'));$('.close').focus()}
