function mealForm(){const hour=new Date().getHours(),type=hour<11?'Breakfast':hour<16?'Lunch':hour<22?'Dinner':'Snack';showModal(`${heading('Add a meal','Nutrition')}<p>Enter what you know. Values from a label or another app work best.</p><form id="manual-meal-form"><label class="field">What you ate<input name="name" required maxlength="200" placeholder="e.g. Greek yogurt with berries"></label><div class="form-grid"><label class="field">Meal<select name="meal_type">${['Breakfast','Lunch','Dinner','Snack'].map(t=>`<option ${t===type?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Day<input name="logged_on" type="date" required max="${localDay()}" value="${nutritionDay}"></label><label class="field">Calories (kcal)<input name="calories" type="number" required min="0" max="10000" step="1" inputmode="numeric"></label><label class="field">Protein (g)<input name="protein" type="number" required min="0" max="10000" step="0.1" value="0"></label><label class="field">Carbs (g)<input name="carbs" type="number" required min="0" max="10000" step="0.1" value="0"></label><label class="field">Fat (g)<input name="fat" type="number" required min="0" max="10000" step="0.1" value="0"></label></div><div id="form-error"></div><div class="dialog-footer"><span>Saved to your food journal.</span><button class="btn" type="submit">Add meal</button></div></form>`);$('#manual-meal-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{const v=Object.fromEntries(new FormData(e.target));await data.saveMeals([{...v,source:'Manual entry'}]);closeModal();nutritionDay=v.logged_on;page='Nutrition';await settle();toast('Meal added')})}}
